/**
 * Chain dashboard — read-only pipeline view (spec §2.5).
 *
 * Pure module: `renderDashboard(index)` turns the committed memo index
 * (web/src/memos-index.json, generated by scripts/build-memo-index.mjs)
 * into HTML. No fetching, no editing, no prices — the dashboard lists
 * memos from the committed index (recorded runs), not live data, and
 * metering is aggregate counts only (hooks for future pricing, not
 * pricing itself). No in-dashboard editing of memos.
 */
export type MemoStatus = "draft" | "delivered" | "decided" | "outcome-recorded";

export interface MemoIndexOutcome {
  memoId: string;
  candidateId: string;
  decision: "signed" | "opened" | "passed";
  actualDailyCustomersMean: number | null;
  actualTrafficTier: "high" | "medium" | "low" | null;
  measurementMethod: "customer-counts" | "pos-transactions";
  projectedLow: number;
  projectedHigh: number;
  observedAt: string;
  source: string;
  _example?: boolean;
}

export interface MemoIndexMemo {
  memoId: string;
  market: string;
  business: string;
  status: MemoStatus;
  topCandidate: string | null;
  band: { low: number; high: number } | null;
  outcome?: MemoIndexOutcome;
}

export interface MemoIndexCalibration {
  market: string;
  version: string;
  runDate: string | null;
}

export interface MemoIndex {
  generatedAt: string;
  memos: MemoIndexMemo[];
  metering: { memosGenerated: number; marketsUsed: string[]; outcomesRecorded: number };
  calibration?: MemoIndexCalibration[];
  accountId: string | null;
  _note?: string;
}

const esc = (s: unknown): string =>
  String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c] as string);

const STATUS_LABELS: Record<MemoStatus, string> = {
  draft: "Draft",
  delivered: "Delivered",
  decided: "Decided",
  "outcome-recorded": "Outcome recorded",
};

function outcomeCell(m: MemoIndexMemo): string {
  if (!m.outcome) return "—";
  const o = m.outcome;
  const actual =
    o.actualDailyCustomersMean !== null
      ? `${o.actualDailyCustomersMean} customers/day`
      : o.actualTrafficTier !== null
        ? `tier ${o.actualTrafficTier}`
        : "no traffic yet";
  return `${esc(o.decision)} · ${esc(actual)} · ${esc(o.measurementMethod)} · ${esc(o.observedAt)}${o._example === true ? " (example)" : ""}`;
}

/** Read-only pipeline view: every memo (city, business, status, top candidate, band, outcome) + metering + calibration. */
export function renderDashboard(index: MemoIndex): string {
  if (index.memos.length === 0) {
    return `<div class="block empty"><p class="h3">No memos yet</p><p class="muted">Run your first memo — it will appear here with its pipeline status.</p></div>`;
  }
  const rows = index.memos
    .map(
      (m) => `<tr>
        <td><b>${esc(m.memoId)}</b>${m.outcome?._example === true ? ` <span class="muted xs">(example)</span>` : ""}<br><span class="muted xs">${esc(m.business)}</span></td>
        <td>${esc(m.market)}</td>
        <td>${esc(STATUS_LABELS[m.status])}</td>
        <td>${m.topCandidate !== null ? esc(m.topCandidate) : "—"}</td>
        <td>${m.band !== null ? `${m.band.low}–${m.band.high}` : "—"}</td>
        <td>${outcomeCell(m)}</td>
      </tr>`,
    )
    .join("");
  const calibration =
    index.calibration !== undefined && index.calibration.length > 0
      ? `<div class="block"><p class="h3">Calibration status</p><ul>${index.calibration
          .map(
            (c) =>
              `<li><b>${esc(c.market)}</b> — weights ${esc(c.version)} · ${
                c.runDate !== null ? `bench run ${esc(c.runDate)}` : "no bench run yet"
              }</li>`,
          )
          .join("")}</ul></div>`
      : "";
  return `<div class="block">
    <p class="muted xs">Pipeline · generated ${esc(index.generatedAt)} · read-only — memos are generated and recorded from the CLI; nothing here edits them.</p>
    <div class="kpis">
      <div class="kpi"><b>${index.metering.memosGenerated}</b><span>memos generated</span></div>
      <div class="kpi"><b>${index.metering.marketsUsed.length}</b><span>markets used</span></div>
      <div class="kpi"><b>${index.metering.outcomesRecorded}</b><span>outcomes recorded</span></div>
    </div>
    <div class="table-wrap"><table>
      <thead><tr><th>Memo</th><th>Market</th><th>Status</th><th>Top candidate</th><th>Projected traffic</th><th>Outcome</th></tr></thead>
      <tbody>${rows}</tbody>
    </table></div>
  </div>${calibration}`;
}
